import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh nodes are followers in term 0', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout starts an election and sends RequestVote', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('nx')).ok, false);
});

test('a single candidate wins', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1' });
  assert.equal((await h.timeout('n0')).ok, false);
});

test('vote reply carries term and granted', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const rv = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual({ from: reply.from, to: reply.to, data: reply.data }, { from: 'n1', to: 'n0', data: { term: 1, granted: true } });
});

test('three candidates: nobody wins, nobody votes twice', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.timeout(n), { ok: true });
  await h.deliverAll();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'candidate', term: 1, votedFor: n });
});

test('random orders: at most one leader, leader has majority', async () => {
  for (let seed = 1; seed <= 30; seed++) {
    let s = seed;
    const rnd = (k: number) => { s = (s * 1103515245 + 12345) % 2147483648; return s % k; };
    const h = await createHost();
    const starters = NODES.filter(() => rnd(2) === 0);
    for (const n of starters) await h.timeout(n);
    for (;;) {
      const msgs = await h.inFlight();
      if (!msgs.length) break;
      await h.deliver(msgs[rnd(msgs.length)].id);
      if (rnd(4) === 0) { const n = NODES[rnd(3)]; await h.timeout(n); }
    }
    const views = await Promise.all(NODES.map((n) => h.node(n)));
    const leaders = NODES.filter((_, i) => views[i]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) assert.ok(views.filter((v) => v!.votedFor === l).length >= 2);
  }
});

